-- M7 POST-STEP67 FRESH PRICING/CATALOG SUCCESSOR 01 — OFFLINE CANDIDATE ONLY.
-- Additive trusted_v3 authority. Does NOT replace or edit trusted_v1/trusted_v2.
\set ON_ERROR_STOP on
BEGIN;
DO $pre$ DECLARE v_owner oid; BEGIN
 SELECT oid INTO v_owner FROM pg_roles WHERE rolname='live_ai_03b_fn_owner' AND NOT rolcanlogin AND NOT rolsuper; IF v_owner IS NULL THEN RAISE EXCEPTION 'M7_V3_MIGRATION: fn_owner shape invalid'; END IF;
 PERFORM 1 FROM pg_roles WHERE rolname='live_ai_03b_executor' AND rolcanlogin AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolbypassrls AND NOT rolreplication; IF NOT FOUND THEN RAISE EXCEPTION 'M7_V3_MIGRATION: executor shape invalid'; END IF;
 IF to_regclass('live_ai_03b_trusted.approval_consumption') IS NULL THEN RAISE EXCEPTION 'M7_V3_MIGRATION: M6 ledger absent'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='live_ai_03b_trusted_v2') OR (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='live_ai_03b_trusted_v2')<>2 THEN RAISE EXCEPTION 'M7_V3_MIGRATION: frozen trusted_v2 predecessor absent/inexact'; END IF;
 IF EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='live_ai_03b_trusted_v3') THEN RAISE EXCEPTION 'M7_V3_MIGRATION: trusted_v3 already exists'; END IF;
 IF NOT(has_table_privilege('live_ai_03b_fn_owner','public.budget_price_catalog_versions','SELECT') AND has_table_privilege('live_ai_03b_fn_owner','public.budget_price_catalog_versions','UPDATE') AND has_table_privilege('live_ai_03b_fn_owner','public.budget_price_catalog_entries','SELECT') AND has_table_privilege('live_ai_03b_fn_owner','public.budget_price_catalog_entries','UPDATE')) THEN RAISE EXCEPTION 'M7_V3_MIGRATION: fn_owner lifecycle privileges missing'; END IF;
END $pre$;
CREATE SCHEMA live_ai_03b_trusted_v3 AUTHORIZATION live_ai_03b_fn_owner;
REVOKE ALL ON SCHEMA live_ai_03b_trusted_v3 FROM PUBLIC;
GRANT USAGE ON SCHEMA live_ai_03b_trusted_v3 TO live_ai_03b_executor;
CREATE FUNCTION live_ai_03b_trusted_v3.activate_catalog_v3(claims_json jsonb,p_execution_id text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $fn$
DECLARE v_now timestamptz; v_consumed timestamptz; v_keys text[]; v_approval text; v_content text; v_updated int; v_nbf timestamptz; v_exp timestamptz; v_evv timestamptz; v_eve timestamptz; BEGIN
 IF claims_json IS NULL OR jsonb_typeof(claims_json) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'activate_v3: claims object required'; END IF;
 SELECT array_agg(k ORDER BY k COLLATE pg_catalog."C") INTO v_keys FROM jsonb_object_keys(claims_json) AS k;
 IF v_keys IS DISTINCT FROM ARRAY['account_mode','activation_bundle_digest','active_catalog_digest','ai_staging_postgres','ai_staging_project','approval_expiry','approval_id','approval_not_before','base_commit','cache_write_rate_micros','catalog_verification_expiry','catalog_version_id','content_digest','context_tier','contract','core_excluded_postgres','core_excluded_project','currency','evidence_expiry','evidence_verified_at','execution_id','inactive_catalog_digest','input_rate_micros','model','one_call_money_ceiling_micros','one_call_policy_digest','one_call_policy_id','output_rate_micros','processing_mode','provider','receipt_id','regional_uplift','reviewer_fingerprint','service_tier','source_digest','unit_size']::text[] THEN RAISE EXCEPTION 'activate_v3: claims key set mismatch'; END IF;
 IF claims_json->>'contract' IS DISTINCT FROM 'VerifiedApprovalClaimsV3' THEN RAISE EXCEPTION 'activate_v3: contract mismatch'; END IF;
 v_approval:=claims_json->>'approval_id'; v_content:=claims_json->>'content_digest';
 IF v_approval IS NULL OR v_approval!~'^[A-Za-z0-9._:-]{8,128}$' OR p_execution_id IS NULL OR p_execution_id!~'^[A-Za-z0-9._:-]{8,128}$' OR claims_json->>'execution_id' IS DISTINCT FROM p_execution_id OR v_content IS NULL OR v_content!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'activate_v3: identifiers malformed'; END IF;
 IF claims_json->>'catalog_version_id' IS DISTINCT FROM 'openai-gpt-5-6-terra-standard-short-v3' OR claims_json->>'source_digest' IS DISTINCT FROM '13c536bcc4afbc6d2706468f072528fc4f7737919c6917653218eb861964ba9a' OR claims_json->>'inactive_catalog_digest' IS DISTINCT FROM '414d4844d10222473b68e2574676fcc3049e025b6b84f2c32a1fbf3c73bd9d74' OR claims_json->>'active_catalog_digest' IS DISTINCT FROM 'bc38931203f797d0360818de429e618a1407fc7f9065f9da7257e6c686c10558' OR claims_json->>'catalog_verification_expiry' IS DISTINCT FROM '2026-10-13T22:44:42Z' OR claims_json->>'activation_bundle_digest' IS DISTINCT FROM '6daa1c678589124cc9a0b01ab7d54aa8b0f46f1d80f4489c0f54cc6cbcacd8bc' THEN RAISE EXCEPTION 'activate_v3: catalog/bundle binding mismatch'; END IF;
 IF claims_json->>'one_call_policy_id' IS DISTINCT FROM 'live-ai-03b-policy-oneprobe-v2' OR claims_json->>'one_call_policy_digest' IS DISTINCT FROM '864e24817b2f98d741495bb403c20ada31cd4f27db3d9dfe1c50bb7d99ad9245' OR claims_json->'one_call_money_ceiling_micros' IS DISTINCT FROM '105920'::jsonb THEN RAISE EXCEPTION 'activate_v3: policy binding mismatch'; END IF;
 IF claims_json->>'provider' IS DISTINCT FROM 'openai' OR claims_json->>'model' IS DISTINCT FROM 'gpt-5.6-terra' OR claims_json->>'account_mode' IS DISTINCT FROM 'direct' OR claims_json->>'processing_mode' IS DISTINCT FROM 'standard' OR claims_json->>'service_tier' IS DISTINCT FROM 'default' OR claims_json->>'context_tier' IS DISTINCT FROM 'short' OR claims_json->'regional_uplift' IS DISTINCT FROM 'false'::jsonb OR claims_json->>'currency' IS DISTINCT FROM 'USD' OR claims_json->'unit_size' IS DISTINCT FROM '1000000'::jsonb OR claims_json->'input_rate_micros' IS DISTINCT FROM '2000000'::jsonb OR claims_json->'cache_write_rate_micros' IS DISTINCT FROM '2500000'::jsonb OR claims_json->'output_rate_micros' IS DISTINCT FROM '12000000'::jsonb THEN RAISE EXCEPTION 'activate_v3: pricing facts mismatch'; END IF;
 IF claims_json->>'base_commit' IS DISTINCT FROM '9270c282d5fd65e9fe49261391badfe92c777b8f' OR claims_json->>'ai_staging_project' IS DISTINCT FROM '4ad1abb3-823a-4acf-b889-6d34ae46d7f9' OR claims_json->>'ai_staging_postgres' IS DISTINCT FROM 'b7362594-a01b-4623-a982-394707a6cec2' OR claims_json->>'core_excluded_project' IS DISTINCT FROM '04c8b523-5b15-4d81-af06-8c2aa1a83499' OR claims_json->>'core_excluded_postgres' IS DISTINCT FROM '1fbd7632-95ad-46f3-a20c-5be5b8e44e6b' THEN RAISE EXCEPTION 'activate_v3: target/source mismatch'; END IF;
 BEGIN v_nbf:=(claims_json->>'approval_not_before')::timestamptz; v_exp:=(claims_json->>'approval_expiry')::timestamptz; v_evv:=(claims_json->>'evidence_verified_at')::timestamptz; v_eve:=(claims_json->>'evidence_expiry')::timestamptz; EXCEPTION WHEN others THEN RAISE EXCEPTION 'activate_v3: approval/evidence timestamps malformed'; END;
 IF NOT(v_nbf<v_exp AND v_evv<v_eve) OR v_evv<TIMESTAMPTZ '2026-10-06T22:44:42Z' OR v_eve>TIMESTAMPTZ '2026-10-13T22:44:42Z' OR v_exp>TIMESTAMPTZ '2026-10-13T22:44:42Z' THEN RAISE EXCEPTION 'activate_v3: approval/evidence interval outside V3 window'; END IF;
 -- A1 R1: acquire every lock that can legitimately wait BEFORE sampling the mutation-boundary clock.
 LOCK TABLE live_ai_03b_trusted.approval_consumption IN SHARE ROW EXCLUSIVE MODE;
 PERFORM 1 FROM public.budget_price_catalog_versions FOR UPDATE; PERFORM 1 FROM public.budget_price_catalog_entries FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.budget_price_catalog_versions WHERE status<>'inactive') OR EXISTS(SELECT 1 FROM public.budget_price_catalog_entries WHERE status<>'inactive') OR (SELECT count(*) FROM public.budget_price_catalog_versions)<>3 OR (SELECT count(*) FROM public.budget_price_catalog_entries)<>8 THEN RAISE EXCEPTION 'activate_v3: predecessor catalog state unexpected'; END IF;
 
 IF NOT EXISTS(SELECT 1 FROM public.budget_price_catalog_versions WHERE (id='openai-gpt-5-6-terra-standard-short-v1' AND status='inactive' AND effective_from=TIMESTAMPTZ '2026-09-18T18:37:35Z' AND effective_until IS NULL AND catalog_digest='453f928762b8e6cddedac8618786d008cb7a3d57ffefab9d0cfe3cda52c4c973' AND created_at=TIMESTAMPTZ '2026-09-18T18:37:35Z')) THEN RAISE EXCEPTION 'activate_v3: historical V1 version mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.budget_price_catalog_versions WHERE (id='openai-gpt-5-6-terra-standard-short-v2' AND status='inactive' AND effective_from=TIMESTAMPTZ '2026-09-28T15:26:23Z' AND effective_until IS NULL AND catalog_digest='36355fab5be8009fa66352ce678394d4963f2927a39d1a8eea63f4aa5b939b62' AND created_at=TIMESTAMPTZ '2026-09-28T15:26:23Z')) THEN RAISE EXCEPTION 'activate_v3: historical V2 version mismatch'; END IF;
 IF (SELECT count(*) FROM public.budget_price_catalog_entries WHERE catalog_version_id='openai-gpt-5-6-terra-standard-short-v1')<>2 THEN RAISE EXCEPTION 'activate_v3: historical V1 entry count mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.budget_price_catalog_entries WHERE (id='openai-gpt-5-6-terra-standard-short-v1-reasoning-input-token-base' AND catalog_version_id='openai-gpt-5-6-terra-standard-short-v1' AND provider='openai' AND model='gpt-5.6-terra' AND service_tier IS NULL AND billing_dimension='reasoning_input_token' AND currency_code='USD' AND unit_size=1000000 AND rate_micros=2000000 AND effective_from=TIMESTAMPTZ '2026-09-18T18:37:35Z' AND effective_until IS NULL AND verified_at=TIMESTAMPTZ '2026-09-18T18:37:35Z' AND verification_expires_at=TIMESTAMPTZ '2026-09-25T18:37:35Z' AND source_id='openai-api-pricing/gpt-5.6-terra/standard/short-context/v1' AND source_digest='fda6f4a834b2277bd0ace30738cda1e8f75c0f8bc523ddbd11c966c4da52beb3' AND status='inactive' AND created_at=TIMESTAMPTZ '2026-09-18T18:37:35Z')) THEN RAISE EXCEPTION 'activate_v3: historical V1 entry mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.budget_price_catalog_entries WHERE (id='openai-gpt-5-6-terra-standard-short-v1-reasoning-output-token-base' AND catalog_version_id='openai-gpt-5-6-terra-standard-short-v1' AND provider='openai' AND model='gpt-5.6-terra' AND service_tier IS NULL AND billing_dimension='reasoning_output_token' AND currency_code='USD' AND unit_size=1000000 AND rate_micros=12000000 AND effective_from=TIMESTAMPTZ '2026-09-18T18:37:35Z' AND effective_until IS NULL AND verified_at=TIMESTAMPTZ '2026-09-18T18:37:35Z' AND verification_expires_at=TIMESTAMPTZ '2026-09-25T18:37:35Z' AND source_id='openai-api-pricing/gpt-5.6-terra/standard/short-context/v1' AND source_digest='fda6f4a834b2277bd0ace30738cda1e8f75c0f8bc523ddbd11c966c4da52beb3' AND status='inactive' AND created_at=TIMESTAMPTZ '2026-09-18T18:37:35Z')) THEN RAISE EXCEPTION 'activate_v3: historical V1 entry mismatch'; END IF;
 IF (SELECT count(*) FROM public.budget_price_catalog_entries WHERE catalog_version_id='openai-gpt-5-6-terra-standard-short-v2')<>3 THEN RAISE EXCEPTION 'activate_v3: historical V2 entry count mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.budget_price_catalog_entries WHERE (id='openai-gpt-5-6-terra-standard-short-v2-reasoning-input-token-base' AND catalog_version_id='openai-gpt-5-6-terra-standard-short-v2' AND provider='openai' AND model='gpt-5.6-terra' AND service_tier IS NULL AND billing_dimension='reasoning_input_token' AND currency_code='USD' AND unit_size=1000000 AND rate_micros=2000000 AND effective_from=TIMESTAMPTZ '2026-09-28T15:26:23Z' AND effective_until IS NULL AND verified_at=TIMESTAMPTZ '2026-09-28T15:26:23Z' AND verification_expires_at=TIMESTAMPTZ '2026-10-05T15:26:23Z' AND source_id='openai-api-pricing/gpt-5.6-terra/standard/short-context/v1' AND source_digest='ec23657bf0c20390afec4d4f233f14300e43b136cc6f27c25d6ffc35e1d7b357' AND status='inactive' AND created_at=TIMESTAMPTZ '2026-09-28T15:26:23Z')) THEN RAISE EXCEPTION 'activate_v3: historical V2 entry mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.budget_price_catalog_entries WHERE (id='openai-gpt-5-6-terra-standard-short-v2-reasoning-input-token-cache-write' AND catalog_version_id='openai-gpt-5-6-terra-standard-short-v2' AND provider='openai' AND model='gpt-5.6-terra' AND service_tier='cache_write' AND billing_dimension='reasoning_input_token' AND currency_code='USD' AND unit_size=1000000 AND rate_micros=2500000 AND effective_from=TIMESTAMPTZ '2026-09-28T15:26:23Z' AND effective_until IS NULL AND verified_at=TIMESTAMPTZ '2026-09-28T15:26:23Z' AND verification_expires_at=TIMESTAMPTZ '2026-10-05T15:26:23Z' AND source_id='openai-api-pricing/gpt-5.6-terra/standard/short-context/v1' AND source_digest='ec23657bf0c20390afec4d4f233f14300e43b136cc6f27c25d6ffc35e1d7b357' AND status='inactive' AND created_at=TIMESTAMPTZ '2026-09-28T15:26:23Z')) THEN RAISE EXCEPTION 'activate_v3: historical V2 entry mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.budget_price_catalog_entries WHERE (id='openai-gpt-5-6-terra-standard-short-v2-reasoning-output-token-base' AND catalog_version_id='openai-gpt-5-6-terra-standard-short-v2' AND provider='openai' AND model='gpt-5.6-terra' AND service_tier IS NULL AND billing_dimension='reasoning_output_token' AND currency_code='USD' AND unit_size=1000000 AND rate_micros=12000000 AND effective_from=TIMESTAMPTZ '2026-09-28T15:26:23Z' AND effective_until IS NULL AND verified_at=TIMESTAMPTZ '2026-09-28T15:26:23Z' AND verification_expires_at=TIMESTAMPTZ '2026-10-05T15:26:23Z' AND source_id='openai-api-pricing/gpt-5.6-terra/standard/short-context/v1' AND source_digest='ec23657bf0c20390afec4d4f233f14300e43b136cc6f27c25d6ffc35e1d7b357' AND status='inactive' AND created_at=TIMESTAMPTZ '2026-09-28T15:26:23Z')) THEN RAISE EXCEPTION 'activate_v3: historical V2 entry mismatch'; END IF;
 
 
 IF (SELECT count(*) FROM public.budget_policy_versions)<>1 OR NOT EXISTS(SELECT 1 FROM public.budget_policy_versions WHERE id='live-ai-03b-policy-v1-dormant' AND project_id='live-ai-03b' AND status='inactive' AND effective_from=TIMESTAMPTZ '2026-09-18T14:11:25Z' AND effective_until IS NULL AND session_money_ceiling_micros=0 AND session_provider_calls=0 AND session_execution_admissions=0 AND subject_day_money_ceiling_micros=0 AND project_day_money_ceiling_micros=0 AND project_month_money_ceiling_micros=0 AND global_day_money_ceiling_micros=0 AND policy_digest='cf5ae64ff17eca76ac3f19c4dd2b5157a1b9bb601f765978e24eb47bbc2308c4' AND created_at=TIMESTAMPTZ '2026-09-18T14:11:25Z') THEN RAISE EXCEPTION 'activate_v3: dormant policy mismatch'; END IF;
 IF (SELECT count(*) FROM public.budget_control_epochs)<>2 OR NOT EXISTS(SELECT 1 FROM public.budget_control_epochs WHERE scope_type='global' AND scope_key_digest='global' AND control_epoch=1 AND enabled=false AND killed=false AND record_digest='26136eb93212ccce1ba6f4b380dbb3f1f2ef64e3d16fa9754e287459cce525ee') OR NOT EXISTS(SELECT 1 FROM public.budget_control_epochs WHERE scope_type='project' AND scope_key_digest='live-ai-03b' AND control_epoch=1 AND enabled=false AND killed=false AND record_digest='be70f6b477c7332a834720e4f784a7d724a6363d48cbcc590315ff2fc72cad7f') THEN RAISE EXCEPTION 'activate_v3: dormant controls mismatch'; END IF;
 
 IF NOT EXISTS(SELECT 1 FROM public.budget_price_catalog_versions WHERE (id='openai-gpt-5-6-terra-standard-short-v3' AND status='inactive' AND effective_from=TIMESTAMPTZ '2026-10-06T22:44:42Z' AND effective_until IS NULL AND catalog_digest='414d4844d10222473b68e2574676fcc3049e025b6b84f2c32a1fbf3c73bd9d74' AND created_at=TIMESTAMPTZ '2026-10-06T22:44:42Z')) OR NOT (EXISTS(SELECT 1 FROM public.budget_price_catalog_entries WHERE (id='openai-gpt-5-6-terra-standard-short-v3-reasoning-input-token-base' AND catalog_version_id='openai-gpt-5-6-terra-standard-short-v3' AND provider='openai' AND model='gpt-5.6-terra' AND service_tier IS NULL AND billing_dimension='reasoning_input_token' AND currency_code='USD' AND unit_size=1000000 AND rate_micros=2000000 AND effective_from=TIMESTAMPTZ '2026-10-06T22:44:42Z' AND effective_until IS NULL AND verified_at=TIMESTAMPTZ '2026-10-06T22:44:42Z' AND verification_expires_at=TIMESTAMPTZ '2026-10-13T22:44:42Z' AND source_id='openai-api-pricing/gpt-5.6-terra/standard/short-context/v1' AND source_digest='13c536bcc4afbc6d2706468f072528fc4f7737919c6917653218eb861964ba9a' AND status='inactive' AND created_at=TIMESTAMPTZ '2026-10-06T22:44:42Z')) AND EXISTS(SELECT 1 FROM public.budget_price_catalog_entries WHERE (id='openai-gpt-5-6-terra-standard-short-v3-reasoning-input-token-cache-write' AND catalog_version_id='openai-gpt-5-6-terra-standard-short-v3' AND provider='openai' AND model='gpt-5.6-terra' AND service_tier='cache_write' AND billing_dimension='reasoning_input_token' AND currency_code='USD' AND unit_size=1000000 AND rate_micros=2500000 AND effective_from=TIMESTAMPTZ '2026-10-06T22:44:42Z' AND effective_until IS NULL AND verified_at=TIMESTAMPTZ '2026-10-06T22:44:42Z' AND verification_expires_at=TIMESTAMPTZ '2026-10-13T22:44:42Z' AND source_id='openai-api-pricing/gpt-5.6-terra/standard/short-context/v1' AND source_digest='13c536bcc4afbc6d2706468f072528fc4f7737919c6917653218eb861964ba9a' AND status='inactive' AND created_at=TIMESTAMPTZ '2026-10-06T22:44:42Z')) AND EXISTS(SELECT 1 FROM public.budget_price_catalog_entries WHERE (id='openai-gpt-5-6-terra-standard-short-v3-reasoning-output-token-base' AND catalog_version_id='openai-gpt-5-6-terra-standard-short-v3' AND provider='openai' AND model='gpt-5.6-terra' AND service_tier IS NULL AND billing_dimension='reasoning_output_token' AND currency_code='USD' AND unit_size=1000000 AND rate_micros=12000000 AND effective_from=TIMESTAMPTZ '2026-10-06T22:44:42Z' AND effective_until IS NULL AND verified_at=TIMESTAMPTZ '2026-10-06T22:44:42Z' AND verification_expires_at=TIMESTAMPTZ '2026-10-13T22:44:42Z' AND source_id='openai-api-pricing/gpt-5.6-terra/standard/short-context/v1' AND source_digest='13c536bcc4afbc6d2706468f072528fc4f7737919c6917653218eb861964ba9a' AND status='inactive' AND created_at=TIMESTAMPTZ '2026-10-06T22:44:42Z'))) THEN RAISE EXCEPTION 'activate_v3: V3 inactive state mismatch'; END IF;
 -- A1 R1: fresh DB clock AFTER all potentially blocking locks/precondition reads and immediately before mutations.
 v_now:=clock_timestamp();
 IF v_now<TIMESTAMPTZ '2026-10-06T22:44:42Z' OR v_now>=TIMESTAMPTZ '2026-10-13T22:44:42Z' OR v_now<v_nbf OR v_now>=v_exp OR v_now<v_evv OR v_now>=v_eve THEN RAISE EXCEPTION 'activate_v3: mutation-boundary freshness failed'; END IF;
 BEGIN INSERT INTO live_ai_03b_trusted.approval_consumption(approval_id,execution_id,content_digest,active_catalog_digest,action) VALUES(v_approval,p_execution_id,v_content,'bc38931203f797d0360818de429e618a1407fc7f9065f9da7257e6c686c10558','activate') RETURNING consumed_at INTO v_consumed; EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'activate_v3: approval already consumed'; END;
 -- Re-sample after the ledger mutation. The broad ledger lock prevents a uniqueness wait from spanning expiry.
 v_now:=clock_timestamp();
 IF v_now>=TIMESTAMPTZ '2026-10-13T22:44:42Z' OR v_now>=v_exp OR v_now>=v_eve THEN RAISE EXCEPTION 'activate_v3: freshness expired before catalog mutation'; END IF;
 UPDATE public.budget_price_catalog_versions SET status='active',catalog_digest='bc38931203f797d0360818de429e618a1407fc7f9065f9da7257e6c686c10558' WHERE id='openai-gpt-5-6-terra-standard-short-v3' AND status='inactive' AND clock_timestamp()>=TIMESTAMPTZ '2026-10-06T22:44:42Z' AND clock_timestamp()<TIMESTAMPTZ '2026-10-13T22:44:42Z' AND clock_timestamp()>=v_nbf AND clock_timestamp()<v_exp AND clock_timestamp()>=v_evv AND clock_timestamp()<v_eve;
 GET DIAGNOSTICS v_updated=ROW_COUNT; IF v_updated<>1 THEN RAISE EXCEPTION 'activate_v3: version mutation refused by live freshness/state predicate'; END IF;
 UPDATE public.budget_price_catalog_entries SET status='active' WHERE catalog_version_id='openai-gpt-5-6-terra-standard-short-v3' AND status='inactive' AND clock_timestamp()>=TIMESTAMPTZ '2026-10-06T22:44:42Z' AND clock_timestamp()<TIMESTAMPTZ '2026-10-13T22:44:42Z' AND clock_timestamp()>=v_nbf AND clock_timestamp()<v_exp AND clock_timestamp()>=v_evv AND clock_timestamp()<v_eve;
